{
  "plan": [
    {
      "step": 1,
      "name": "search_federal_contracts",
      "description": "Retrieve federal constituency project exercise-book contracts (2020-2024)",
      "tool": "searchFederalBookContracts",
      "parameters": {
        "year_range": "2020-2024",
        "spec_filters": ["leaves", "gsm", "cover_type"]
      },
      "outputs": ["contract_id", "constituency", "state", "award_year", "supplier", "quantity", "total_value", "spec_summary"]
    },
    {
      "step": 2,
      "name": "search_oyo_contracts",
      "description": "Retrieve Oyo state exercise-book procurement contracts (2020-2024)",
      "tool": "searchOyoBookContracts",
      "parameters": {
        "year_range": "2020-2024",
        "spec_filters": ["leaves", "gsm", "cover_type"]
      },
      "outputs": ["contract_id", "award_year", "supplier", "quantity", "total_value", "spec_summary"]
    },
    {
      "step": 3,
      "name": "get_federal_items",
      "description": "Fetch detailed line items for federal contracts",
      "tool": "getFederalBookContractItems",
      "parameters": {
        "contract_ids": "from_step_1"
      },
      "outputs": ["contract_id", "item_id", "leaves", "gsm", "cover_type", "size", "binding", "unit_price", "quantity"]
    },
    {
      "step": 4,
      "name": "get_oyo_items",
      "description": "Fetch detailed line items for Oyo contracts",
      "tool": "searchOyoBookContracts",
      "parameters": {
        "contract_ids": "from_step_2",
        "include_items": true
      },
      "outputs": ["contract_id", "item_id", "leaves", "gsm", "cover_type", "size", "binding", "unit_price", "quantity"]
    },
    {
      "step": 5,
      "name": "standardize_specs",
      "description": "Normalize specifications into comparable tiers",
      "rule": "Create spec_key = leaves|gsm|cover_type|size|binding; group by spec_key"
    },
    {
      "step": 6,
      "name": "cpi_adjustment",
      "description": "Adjust all unit prices to constant 2024 NGN",
      "tool": "getNigeriaCpi",
      "parameters": {
        "years": "2020-2024"
      },
      "calculation": "real_price_2024 = nominal_price * (CPI_2024 / CPI_award_year)"
    },
    {
      "step": 7,
      "name": "deduplicate",
      "description": "Remove duplicate contract lines",
      "keys": ["contract_id", "item_id", "supplier", "spec_key", "quantity", "unit_price"],
      "rule": "Keep first; log duplicates"
    },
    {
      "step": 8,
      "name": "twin_award_check",
      "description": "Flag twin awards: same spec, year, constituency/state, similar quantity/price to different suppliers",
      "match_fields": ["jurisdiction", "award_year", "spec_key"],
      "tolerances": {
        "quantity_pct": 5,
        "price_pct": 10
      },
      "output": "twin_group_id, twin_flag"
    },
    {
      "step": 9,
      "name": "benchmark_comparison",
      "description": "Compare federal vs Oyo median real prices by spec_key and year",
      "group_by": ["spec_key", "award_year", "jurisdiction"],
      "metrics": ["median_real_price_2024", "p25", "p75", "count"],
      "comparison": "federal_median vs oyo_median per spec_key-year"
    },
    {
      "step": 10,
      "name": "cross_publisher_supplier_check",
      "description": "Check if same suppliers appear across federal and Oyo contracts",
      "tool": "getCrossPublisherSuppliers",
      "parameters": {
        "federal_suppliers": "from_step_1",
        "oyo_suppliers": "from_step_2"
      },
      "output": "common_suppliers, supplier_jurisdiction_map"
    }
  ],
  "tools": [
    "searchFederalBookContracts",
    "getFederalBookContractItems",
    "searchOyoBookContracts",
    "getNigeriaCpi",
    "getCrossPublisherSuppliers"
  ]
}

